export function reportedFor(kind, slug) {
  const key = `${kind}:${slug}`
  return [...(REPORTED[key] || []), ...(REPORTED_SPECIES[key] || [])]
}

export const REPORTED_KEYS = [...new Set([...Object.keys(REPORTED), ...Object.keys(REPORTED_SPECIES)])]
